     public TicketController(PredictionEnginePool<TicketData, TicketPrediction> predictionPool)
     {
         _predictionPool = predictionPool;
     }

     [HttpPost("classify")]
     public ActionResult<TicketClassifyResponse> Classify([FromBody] TicketClassifyRequest request)
     {
         if (!ModelState.IsValid)
         {
             return BadRequest(ModelState);
         }

         var input = new TicketData
         {
             Subject = request.Subject,
             Description = request.Description,
             Priority = request.Priority
         };

         var prediction = _predictionPool.Predict(input);

         var categories = new[] { "Billing", "General", "Technical" };
         var scores = new Dictionary<string, float>();
         for (var i = 0; i < prediction.Score.Length && i < categories.Length; i++)
         {
             scores[categories[i]] = prediction.Score[i];
         }

         var confidence = prediction.Score.Length > 0 ? prediction.Score.Max() : 0f;

         return Ok(new TicketClassifyResponse
         {
             Category = prediction.PredictedLabel,
             Confidence = confidence,
             Scores = scores
         });
     }
 }

 public class TicketClassifyRequest
 {
     [Required]
     public string Subject { get; set; } = string.Empty;

     [Required]
     public string Description { get; set; } = string.Empty;

     [Range(1, 3)]
     public int Priority { get; set; }
 }

 public class TicketClassifyResponse
 {
     public string Category { get; set; } = string.Empty;
     public float Confidence { get; set; }
     public Dictionary<string, float> Scores { get; set; } = new();
 }
